{% set gst_total=[] %}
{% for row in doc.items %}

	<tr style="font-size:12px;">
	        {% set cgst_amt = [] %}
	 	 {% set sgst_amt = [] %}
		 {% set igst_amt = [] %}
		 {% set it_cgst_rate = [] %}
	 	 {% set it_sgst_rate = [] %}
		 {% set it_igst_rate = [] %}
		 {% set rate_found_item = 0 %}
		  {%- set item_record = frappe.get_doc("Item", row.item_code) -%}
			{% for item_tax in item_record.taxes %}

  			  {% if item_tax.item_tax_template == igst_account_head[0] %}

				{% set _ = it_igst_rate.append(item_tax.tax_category) %}
				{% set _ = igst_amt.append(row.amount * it_igst_rate[0] / 100) -%}
				{% set rate_found_item = 1 -%}
			{% endif %}		
			{% if item_tax.item_tax_template == sgst_account_head[0] %}

				{% set _ = it_sgst_rate.append(item_tax.tax_category) %}
				{% set _ = sgst_amt.append(row.amount * it_sgst_rate[0] / 100) -%}
				{% set rate_found_item = 1 -%}
			{% endif %}	
			{% if item_tax.item_tax_template == cgst_account_head[0] %}
				{% set _ = it_cgst_rate.append(item_tax.tax_category) %}
				{% set _ = cgst_amt.append(row.amount * it_cgst_rate[0] / 100) -%}
				{% set rate_found_item = 1 -%}
			{% endif %}		


		{% endfor %}


  	{% if rate_found_item == 0 %}

		{% if cgst_rate[0] -%}
		   {% set _ = cgst_amt.append((row.amount * cgst_rate[0])/100) %}
		   {% set _= it_cgst_rate.append(cgst_rate[0]) %}
		   {% set rate_found_inv = 1 %}
	       	{%- endif %}
		{% if sgst_rate[0] %}
		   {% set _ = sgst_amt.append((row.amount * sgst_rate[0])/100) %}
		   {% set _= it_sgst_rate.append(sgst_rate[0]) %}

	       	{%- endif -%}
		{% if igst_rate[0] %}
		   {% set _ = igst_amt.append((row.amount * igst_rate[0])/100) %}
		   {% set _= it_igst_rate.append(igst_rate[0]) %}
		   {% set rate_found_inv = 1 %}
	       	{% endif %}
	{% endif %}
   {% if not it_cgst_rate[0] %}
		{% set _ = it_cgst_rate.append(0) %}
		{% set _ = cgst_amt.append(0) %}
	{% endif %}
	{% if not it_sgst_rate[0] %}
		{% set _ = it_sgst_rate.append(0) %}
		{% set _ = sgst_amt.append(0) %}
	{% endif %}
	{% if not it_igst_rate[0] %}
		{% set _ = it_igst_rate.append(0) %}
		{% set _ = igst_amt.append(0) %}
	{% endif %}
	{% set temp_cgst_amt = grand_total["cgst_amt"] + cgst_amt[0] %}
	{% set temp_sgst_amt = grand_total["sgst_amt"] + sgst_amt[0] %}
	{% set temp_igst_amt = grand_total["igst_amt"] + igst_amt[0] %}
    {% set temp_amount = grand_total["amount"] + row.amount %}
	{% set check = grand_total.update({"amount": temp_amount, "cgst_amt":temp_cgst_amt, "sgst_amt":temp_sgst_amt, "igst_amt":temp_igst_amt}) %}



	   <td style="border-bottom-style:hidden;"><font size = "">{{ row.gst_hsn_code or ''}}</font></td>

	    <td style=" text-align: right;border-bottom-style:hidden;"> {{
			"  {:,.2f}".format(row.amount)  }}</td>
		<td style="text-align:center;border-bottom-style:hidden;">{{it_cgst_rate[0]}} %</td>
		<td style=" text-align: right;border-bottom-style:hidden;"><font size = ""> {{
			"  {:,.2f}".format(cgst_amt[0])  }}<br><small></small></font></td>
		<td style="text-align:center;border-bottom-style:hidden;">{{it_sgst_rate[0]}} %</td>
		<td style=" text-align: right;border-bottom-style:hidden;"><font size = ""> {{
			" {:,.2f}".format(sgst_amt[0])  }}<br><small></small></font></td>
		<td style="text-align:center;border-bottom-style:hidden;">{{it_igst_rate[0]}} %</td>
		<td style=" text-align: right;border-bottom-style:hidden;"><font size = "">  {{
			" {:,.2f}".format(igst_amt[0])  }}<br><small></small></font></td>
		<td style=" text-align: right;border-bottom-style:hidden;"><font size = ""> {{
			"  {:,.2f}".format(cgst_amt[0]+sgst_amt[0]+igst_amt[0]) }}</font></td>
		{{ total_amt.append(row.amount) or ""}}
	    {{ cgst_total.append(cgst_amt[0]) or ""}}
	    {{ sgst_total.append(sgst_amt[0]) or ""}}
	    {{ igst_total.append(igst_amt[0]) or ""}}
	    {{ gst_total.append(cgst_amt[0]+sgst_amt[0]+igst_amt[0]) or ""}}
</tr>
{% endfor %}
<tr style="line-height:12px;">
    <td></td>
    <td></td>
    <td></td>
    <td></td>
    <td></td>
    <td></td>
    <td></td>
    <td></td>
    <td></td>

</tr>
<tr style="font-size:12px;">
   <td><b>Total</b></td>
   <td style=" text-align: right;font-weight:bold;">{{" {:,.2f}".format(total_amt | sum )}}</td>
    <td></td>
    <td style=" text-align: right;font-weight:bold;">{{" {:,.2f}".format(cgst_total | sum )}}</td>
    <td></td>
    <td style=" text-align: right;font-weight:bold;">{{" {:,.2f}".format(sgst_total | sum) }}</td>
    <td></td>
    <td style=" text-align: right;font-weight:bold;">{{" {:,.2f}".format(igst_total | sum )}}</td>
    <td style=" text-align: right;font-weight:bold;">{{" {:,.2f}".format(gst_total | sum )}}</td>
</tr>
<tr style="font-size:12px;">
    <td colspan="2" style="border-right-style:hidden;"> Tax Amount (in words) :</td>
    <td colspan="7 " style="font-weight:bold;">{{ frappe.utils.money_in_words(doc.total_taxes_and_charges)}}</td>
</td>
</tr>
</tbody>
</table>"}, {"fieldtype": "Section Break", "label": "Terms and Conditions"}, {"fieldtype": "Column Break"}, {"fieldname": "terms", "print_hide": 0, "label": "Terms and Conditions Details"}, {"fieldtype": "Section Break", "label": "More Information"}, {"fieldtype": "Column Break"}, {"fieldname": "inter_company_invoice_reference", "print_hide": 0, "label": "Inter Company Invoice Reference"}, {"fieldname": "represents_company", "print_hide": 0, "label": "Represents Company"}, {"fieldtype": "Column Break"}, {"fieldname": "is_internal_customer", "print_hide": 0, "label": "Is Internal Customer"}, {"fieldname": "is_discounted", "print_hide": 0, "label": "Is Discounted"}, {"fieldtype": "Section Break", "label": "Remarks"}, {"fieldtype": "Column Break"}, {"fieldname": "remarks", "print_hide": 0, "label": "Remarks"}]
